actions.script:
// the playlist as the viewer: a definition they may not read, or one that is no playlist, is not available
playlistTitle = null; playlistSeconds = 30; playlistEntries = []
if (definitionId) {
    ec.message.pushErrors()
    try {
        const definition = ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId}).call()?.definition
        if (!ec.message.hasError() && definition?.type === 'report' && definition.body?.kind === 'playlist') {
            playlistTitle = definition.title || definition.id
            playlistSeconds = Number(definition.body.seconds) || 30
            playlistItems = Array.from(definition.body.playlist || []).slice(0, 50)
        }
    } catch (error) { ec.logger.error('Wall display playlist ' + definitionId + ' unavailable: ' + String(error)) }
    finally { ec.message.clearErrors(); ec.message.popErrors() }
}
// each dashboard as the viewer, as the framework Playlist does: one they may not read is left out and logged by name,
// and keeps its index in the playlist for the data transition
for (const [index, item] of (playlistTitle ? playlistItems : []).entries()) {
    ec.message.pushErrors()
    try {
        const dashboard = ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId: item.definitionId}).call()?.definition
        if (!ec.message.hasError() && dashboard?.type === 'dashboard')
            playlistEntries.push({index, title: dashboard.title || dashboard.id, url: '?definitionId=' + encodeURIComponent(dashboard.id) + '&from=now-30d&thru=now'})
        else ec.logger.error('Wall display playlist ' + definitionId + ': dashboard ' + item.definitionId + ' unavailable')
    } catch (error) { ec.logger.error('Wall display playlist ' + definitionId + ': dashboard ' + item.definitionId + ' unavailable: ' + String(error)) }
    finally { ec.message.clearErrors(); ec.message.popErrors() }
}
// the range is Insights' default (relative, so it needs no zone); the data transition takes the playlist's index
dataSource = sri.buildUrl('data').path + '?definitionId=' + encodeURIComponent(definitionId || '') + '&from=now-30d&thru=now'
// the html page: the theme's style sheets, the qvt client's files and this screen as an island (WebrootPublic.qvt.js)
const qvtLib = ec.resource.script('component://webroot/screen/includes/QvtConfig.js')
const localeTag = String(ec.user.locale || 'en_US').replace('_', '-')
const quasarLang = qvtLib.quasarLangOf(localeTag)
const sheets = Array.from(sri.getThemeValues('STRT_STYLESHEET'))
const scripts = ['/libs/vue/vue.global.prod.js', '/libs/quasar/quasar.umd.prod.js', '/libs/quasar/lang/' + quasarLang + '.umd.prod.js']
if (sheets.some(sheet => String(sheet).includes('/libs/material-symbols/'))) scripts.push('/libs/quasar/icon-set/material-symbols-outlined.umd.prod.js')
scripts.push('/js/MoquiLib.js', '/js/MoquiL10n.js', '/js/WebrootVue.qvt.render.js', '/js/WebrootVue.qvt.js', '/js/WebrootReport.js', '/js/WebrootPublic.qvt.js')
const version = '?v=' + ec.web.getResourceDistinctValue()
const href = location => WebUtilities.encodeHtml(sri.buildUrl(location).url + version)
wallHead = sheets.map(sheet => '<link rel="stylesheet" href="' + href(sheet) + '">').join('')
wallScripts = scripts.map(script => '<script src="' + href(script) + '"></script>').join('')
wallLang = WebUtilities.encodeHtml(localeTag)
wallTitle = WebUtilities.encodeHtml(playlistTitle || ec.l10n.localize('Wall display'))
const island = {
    shell: 'island', sessionToken: ec.web.sessionToken, appRootPath: '', locale: localeTag, timeZone: ec.user.timeZone,
    quasarLang: quasarLang.replace(/-([a-zA-Z])/g, (m, ch) => ch.toUpperCase()),
    qvt: {build: 'compiler', handles: ['merged-fragment', 'static-template']},
    route: {name: 'wall-display', basePath: sri.buildUrl('.').path, title: playlistTitle, renderModes: ['qvt']},
    context: {}, labels: {loading: ec.l10n.localize('Loading'), notFound: ec.l10n.localize('This playlist is not available to this display.')}
}
wallIsland = JSON.stringify(island).split('<').join('\\u003c')
